  final String titlesJson;
  final String rivalsJson;
  final double budget;
  final String stadiumName;
  final String parkFactor;

  const HsSchoolDetail({
    required this.teamId,
    required this.name,
    required this.region,
    required this.stars,
    required this.seasonRanksJson,
    required this.titlesJson,
    required this.rivalsJson,
    required this.budget,
    required this.stadiumName,
    required this.parkFactor,
  });

  @override
  int get hashCode =>
      teamId.hashCode ^
      name.hashCode ^
      region.hashCode ^
      stars.hashCode ^
      seasonRanksJson.hashCode ^
      titlesJson.hashCode ^
      rivalsJson.hashCode ^
      budget.hashCode ^
      stadiumName.hashCode ^
      parkFactor.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is HsSchoolDetail &&
          runtimeType == other.runtimeType &&
          teamId == other.teamId &&
          name == other.name &&
          region == other.region &&
          stars == other.stars &&
          seasonRanksJson == other.seasonRanksJson &&
          titlesJson == other.titlesJson &&
          rivalsJson == other.rivalsJson &&
          budget == other.budget &&
          stadiumName == other.stadiumName &&
          parkFactor == other.parkFactor;
