@freezed
sealed class MatchStepInfo with _$MatchStepInfo {
  const MatchStepInfo._();

  const factory MatchStepInfo.awaitingPitch({
    required String batterId,
    required int balls,
    required int strikes,
    required bool highLeverage,
    required int inning,
    required bool topOfInning,
    required int outs,
    required List<bool> bases,
    required int homeRuns,
    required int awayRuns,

    /// 매치 화면 스태미나 게이지용(§6-N) — `PitcherChangeDecision.fatigue`
    /// 와 같은 값 출처.
    required double fatigue,
    required int pitchesThrown,

    /// 방금 전 타석의 인플레이 타구를 처리한 포지션(대화 2026-07-25,
    /// 매치 화면 수비 배지 하이라이트용) — 없으면(K/BB/HBP였거나
    /// 하프이닝이 막 시작됐으면) `None`.
    String? lastFielderPosition,

    /// `last_fielder_position`이 있을 때만 의미 있음 — 그 플레이가 실책이었는지.
    required bool lastPlayWasError,
  }) = MatchStepInfo_AwaitingPitch;
  const factory MatchStepInfo.gameOver({
    required int homeRuns,
    required int awayRuns,
  }) = MatchStepInfo_GameOver;

  /// 감독 개입(§8) 수동 모드 판단 요청 — `resolveChoice`에 `"유지"`/
  /// `"교체"`/`"맡기기"`를 응답해야 진행된다.
  const factory MatchStepInfo.pitcherChangeDecision({
    required int inning,
    required bool topOfInning,
    required int homeRuns,
    required int awayRuns,
    required int pitchesThrown,
    required double fatigue,
    required bool managerRecommendsPull,
  }) = MatchStepInfo_PitcherChangeDecision;
}

